5	public final class GameOfLife {
6	
7	    private GameOfLife() {
8	    }
9	
10	    public static Set<Cell> nextGeneration(Set<Cell> livingCells) {
11	        return cellsThatCouldChange(livingCells).stream()
12	                .filter(cell -> ConwayRules.isAliveNextGeneration(
13	                        livingCells.contains(cell),
14	                        livingNeighbourCount(cell, livingCells)))
15	                .collect(Collectors.toUnmodifiableSet());
16	    }
17	
18	    private static Set<Cell> cellsThatCouldChange(Set<Cell> livingCells) {
19	        return livingCells.stream()
20	                .flatMap(cell -> Stream.concat(Stream.of(cell), cell.neighbours().stream()))
21	                .collect(Collectors.toUnmodifiableSet());
22	    }
23	
24	    private static int livingNeighbourCount(Cell cell, Set<Cell> livingCells) {
25	        return (int) cell.neighbours().stream().filter(livingCells::contains).count();
26	    }
27	}
