1	public final class ConwayRules {
2	
3	    private ConwayRules() {
4	    }
5	
6	    public static boolean isAliveNextGeneration(boolean currentlyAlive, int livingNeighbours) {
7	        return currentlyAlive
8	                ? survives(livingNeighbours)
9	                : isBorn(livingNeighbours);
10	    }
11	
12	    private static boolean survives(int livingNeighbours) {
13	        return livingNeighbours == 2 || livingNeighbours == 3;
14	    }
15	
16	    private static boolean isBorn(int livingNeighbours) {
17	        return livingNeighbours == 3;
18	    }
19	}
