90	     * Reads the specification's picture notation: '#' is a living cell, '.' is dead.
91	     * The first row is y=0 and the first column is x=0, so board("#", "#", "#")
92	     * is the vertical blinker [(0,0), (0,1), (0,2)].
93	     */
94	    private static Set<Cell> board(String... rows) {
95	        Set<Cell> livingCells = new HashSet<>();
96	        for (int y = 0; y < rows.length; y++) {
97	            for (int x = 0; x < rows[y].length(); x++) {
98	                if (rows[y].charAt(x) == '#') {
99	                    livingCells.add(new Cell(x, y));
100	                }
101	            }
102	        }
103	        return livingCells;
104	    }
