154	        assertEquals(new Cell(1, 2), new Cell(1, 2));
155	        assertEquals(new Cell(1, 2).hashCode(), new Cell(1, 2).hashCode());
156	        assertNotEquals(new Cell(1, 2), new Cell(2, 1));
