import java.util.HashSet;
import java.util.Set;

public record Cell(int x, int y) {

    private static final int ADJACENT_DISTANCE = 1;

    /**
     * The eight coordinates surrounding this cell on the infinite grid.
     * Adjacency is the only topological knowledge in the model.
     */
    public Set<Cell> neighbours() {
        Set<Cell> neighbours = new HashSet<>();
        for (int dx = -ADJACENT_DISTANCE; dx <= ADJACENT_DISTANCE; dx++) {
            for (int dy = -ADJACENT_DISTANCE; dy <= ADJACENT_DISTANCE; dy++) {
                boolean isSelf = dx == 0 && dy == 0;
                if (!isSelf) {
                    neighbours.add(new Cell(x + dx, y + dy));
                }
            }
        }
        return Set.copyOf(neighbours);
    }
}
EOF
